	private static AnimationDefinition create_walk() {
		AnimationDefinition.Builder b = AnimationDefinition.Builder.withLength(2.0F).looping();
		add_walk_0(b);
		add_walk_1(b);
		add_walk_2(b);
		add_walk_3(b);
		return b.build();
	}

