	private static AnimationDefinition create_attack() {
		AnimationDefinition.Builder b = AnimationDefinition.Builder.withLength(1.5F);
		add_attack_0(b);
		add_attack_1(b);
		add_attack_2(b);
		add_attack_3(b);
		return b.build();
	}

