	private static AnimationDefinition create_aggro() {
		AnimationDefinition.Builder b = AnimationDefinition.Builder.withLength(1.6F);
		add_aggro_0(b);
		add_aggro_1(b);
		add_aggro_2(b);
		add_aggro_3(b);
		return b.build();
	}

