	private static AnimationDefinition create_hurt() {
		AnimationDefinition.Builder b = AnimationDefinition.Builder.withLength(0.65F);
		add_hurt_0(b);
		add_hurt_1(b);
		add_hurt_2(b);
		add_hurt_3(b);
		return b.build();
	}

